export const code = async (inputs) => {
  const list = Array.isArray(inputs.records) ? inputs.records : [];
  const overdueDays = Number(inputs.overdueDays) || 0;
  const repeatDays = Number(inputs.repeatDays) || 7;
  const day = 24 * 60 * 60 * 1000;
  const now = Date.now();
  const cell = (record, column) => {
    const found = Object.values((record && record.cells) || {}).find(
      (entry) => String(entry.fieldName ?? '').trim().toLowerCase() === column,
    );
    return found && found.value !== undefined && found.value !== null ? String(found.value).trim() : '';
  };
  const due = [];
  const problems = [];
  for (const record of list) {
    const status = cell(record, 'status').toLowerCase();
    const invoice = cell(record, 'invoice');
    if (status === 'paid' || status === 'cancelled' || invoice === '') {
      continue;
    }
    const dueAt = Date.parse(cell(record, 'due date'));
    const email = cell(record, 'email');
    if (Number.isNaN(dueAt) || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) {
      problems.push(invoice);
      continue;
    }
    const remindedAt = Date.parse(cell(record, 'reminded at'));
    const isOverdue = now - dueAt >= overdueDays * day;
    const recentlyReminded = !Number.isNaN(remindedAt) && now - remindedAt < repeatDays * day;
    if (isOverdue && !recentlyReminded) {
      due.push({
        row: record.id,
        invoice,
        customer: cell(record, 'customer') || 'there',
        email,
        amount: cell(record, 'amount'),
        dueDate: cell(record, 'due date'),
      });
    }
  }
  return { due, count: due.length, problems, checkedAt: new Date(now).toISOString() };
};

