export const code = async (inputs) => {
  const invoices = Array.isArray(inputs.problems) ? inputs.problems : [];
  if (invoices.length > 0) {
    throw new Error(invoices.length + ' invoice(s) skipped - invalid email or due date: ' + invoices.join(', '));
  }
  return { reminded: inputs.count };
};
